import { mulberry32 } from './seed-random.js';

/**
 * Generates a uuidv4
 */
export function uuidv4(seed?: number) {
  // If a seed is given, use a seeded random function to generate the uuid.
  const random = seed !== void 0 ? mulberry32(seed) : Math.random;
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (char) => {
    // eslint-disable-next-line no-mixed-operators
    const randomNumber = (random() * 16) | 0;
    const value = char === 'x' ? randomNumber : (randomNumber & 0x3) | 0x8;
    return value.toString(16);
  });
}
